  "pending": "pendiente",
  "completed": "completado",
  "failed": "fallido",
  "Page {page} of {pages} · {n} scans": { one: "Página {page} de {pages} · {n} escaneo", other: "Página {page} de {pages} · {n} escaneos" },
  "Scan History": "Historial de escaneos",
